insert into stones (slug, name, material, brand, tone, finish, thickness, description_tr, description_en, images, featured, active) values
  ('nero-marquina', 'Nero Marquina', 'mermer', 'İspanya', 'dark', 'Cilalı', '2 cm / 3 cm', 'Derin siyah zemin üzerinde ince, beyaz damarlar. Adımıza ilham veren taş; ada tezgahlarında ve banyo duvarlarında çarpıcı durur.', 'Deep black with fine white veins — the stone that inspired our name. Striking on kitchen islands and bathroom walls.', '["/stones/nero-marquina.jpg"]'::jsonb, true, true),
  ('calacatta-oro', 'Calacatta Oro', 'mermer', 'İtalya', 'light', 'Cilalı', '2 cm / 3 cm', 'Sıcak beyaz zemin, altın ve gri tonlarda geniş damarlar. Klasik ve sıcak bir mutfak için.', 'Warm white with broad gold and grey veining. For a classic, warm kitchen.', '["/stones/calacatta-oro.jpg"]'::jsonb, true, true),
  ('statuario-venato', 'Statuario Venato', 'mermer', 'İtalya', 'light', 'Cilalı', '2 cm', 'Parlak beyaz üzerinde belirgin gri damarlar. Banyo tezgahlarında zamansız bir seçim.', 'Bright white with bold grey veins. A timeless choice for bathroom vanities.', '["/stones/statuario-venato.jpg"]'::jsonb, true, true),
  ('carrara-bianco', 'Carrara Bianco', 'mermer', 'İtalya', 'light', 'Cilalı / Mat', '2 cm', 'Yumuşak gri-beyaz zemin ve dağınık ince damarlar. Sakin ve kolay eşleşen bir mermer.', 'Soft grey-white with scattered fine veins. A calm marble that pairs with almost anything.', '["/stones/carrara-bianco.jpg"]'::jsonb, false, true),
  ('emperador-dark', 'Emperador Dark', 'mermer', 'İspanya', 'warm', 'Cilalı', '2 cm', 'Koyu kahve zemin üzerinde krem damarlar. Ahşap dolaplarla güçlü bir uyum yakalar.', 'Dark brown with cream veins. Works beautifully with wooden cabinetry.', '["/stones/emperador-dark.jpg"]'::jsonb, false, true),
  ('afyon-sugar-white', 'Afyon Sugar', 'mermer', 'Afyon', 'light', 'Cilalı / Honlu', '2 cm', 'Afyon''dan, şeker beyazı zemin ve çok hafif damarlar. Yerli ve zarif.', 'From Afyon, Türkiye: sugar-white with very faint veins. Local and refined.', '["/stones/afyon-sugar-white.jpg"]'::jsonb, false, true),
  ('verde-alpi', 'Verde Alpi', 'mermer', 'İtalya', 'dark', 'Cilalı', '2 cm', 'Koyu yeşil zemin, açık yeşil damarlar. Lavabo ve konsol gibi küçük yüzeylerde dikkat çeker.', 'Deep green with pale green veins. Eye-catching on vanities and console tops.', '["/stones/verde-alpi.jpg"]'::jsonb, false, true),
  ('black-galaxy', 'Black Galaxy', 'granit', 'Hindistan', 'dark', 'Cilalı', '3 cm', 'Siyah zemin üzerinde altın renkli parıltılar. Çok dayanıklı, yoğun kullanılan mutfaklar için.', 'Black with golden flecks. Extremely durable for busy kitchens.', '["/stones/black-galaxy.jpg"]'::jsonb, true, true),
  ('absolute-black', 'Absolute Black', 'granit', 'Zimbabve', 'dark', 'Cilalı / Leather', '3 cm', 'Tek renk, derin siyah granit. Modern mutfaklarda net bir çizgi verir.', 'Solid, deep black granite. Gives a crisp line in modern kitchens.', '["/stones/absolute-black.jpg"]'::jsonb, false, true),
  ('kashmir-white', 'Kashmir White', 'granit', 'Hindistan', 'light', 'Cilalı', '3 cm', 'Kırık beyaz zemin, ince koyu benekler. Granitin dayanıklılığı, açık bir görünümle.', 'Off-white with fine dark specks. Granite toughness in a light look.', '["/stones/kashmir-white.jpg"]'::jsonb, false, true),
  ('steel-grey', 'Steel Grey', 'granit', 'Hindistan', 'dark', 'Cilalı', '3 cm', 'Orta gri, homojen dokulu granit. Dış mekan ve barbekü alanları için de uygun.', 'Even mid-grey granite. Also suitable for outdoor kitchens and barbecues.', '["/stones/steel-grey.jpg"]'::jsonb, false, true),
  ('quartz-pure-white', 'Pure White', 'kuvars', 'Belenco', 'light', 'Cilalı', '2 cm / 3 cm', 'Saf beyaz, desensiz kuvars. Leke tutmaz, bakımı en kolay seçeneklerden.', 'Pure white, patternless quartz. Stain-resistant and among the easiest to care for.', '["/stones/quartz-pure-white.jpg"]'::jsonb, false, true),
  ('quartz-calacatta', 'Calacatta Venato', 'kuvars', 'Silestone', 'light', 'Cilalı', '2 cm', 'Calacatta mermer görünümü, kuvarsın kolay bakımıyla.', 'The look of Calacatta marble with the easy care of quartz.', '["/stones/quartz-calacatta.jpg"]'::jsonb, true, true),
  ('quartz-concrete', 'Concrete Grey', 'kuvars', 'Çimstone', 'dark', 'Mat', '2 cm', 'Brüt beton etkisi veren bulutlu gri yüzey. Endüstriyel mutfaklara uygun.', 'Cloudy grey with a raw concrete feel. Suits industrial-style kitchens.', '["/stones/quartz-concrete.jpg"]'::jsonb, false, true),
  ('quartz-midnight', 'Midnight', 'kuvars', 'Calisco', 'dark', 'Cilalı', '2 cm', 'Gece mavisine çalan koyu zemin, hafif parıltılar.', 'A dark ground leaning to midnight blue, with a light shimmer.', '["/stones/quartz-midnight.jpg"]'::jsonb, false, true),
  ('quartz-carrara', 'Carrara Soft', 'kuvars', 'Coante', 'light', 'Cilalı', '2 cm', 'Carrara''nın yumuşak damarları, homojen kuvars yapısında.', 'Carrara''s soft veins in a consistent quartz body.', '["/stones/quartz-carrara.jpg"]'::jsonb, false, true),
  ('porcelain-nero-venato', 'Nero Venato', 'porselen', 'Neolith', 'dark', 'Mat', '12 mm', 'Siyah zemin, krem damarlar. Isıya ve çizilmeye çok dayanıklı porselen levha.', 'Black with cream veins. A porcelain slab with high heat and scratch resistance.', '["/stones/porcelain-nero-venato.jpg"]'::jsonb, true, true),
  ('porcelain-statuario', 'Statuario Lux', 'porselen', 'Laminam', 'light', 'Parlak', '12 mm', 'İnce porselen levhada statuario görünümü. Geniş yüzeyler için derzsiz uygulama.', 'The statuario look on a thin porcelain slab. Seamless on large surfaces.', '["/stones/porcelain-statuario.jpg"]'::jsonb, false, true),
  ('porcelain-travertino', 'Travertino Classico', 'porselen', 'Dekton', 'warm', 'Mat', '12 mm', 'Bej travertenin yatay damarları; sıcak, akdeniz havası.', 'The horizontal grain of beige travertine — warm and Mediterranean.', '["/stones/porcelain-travertino.jpg"]'::jsonb, false, true),
  ('porcelain-graphite', 'Graphite', 'porselen', 'Lamar', 'dark', 'Mat', '12 mm', 'Koyu grafit, kadifemsi mat yüzey. Parmak izi tutmaz.', 'Dark graphite with a velvety matt finish that hides fingerprints.', '["/stones/porcelain-graphite.jpg"]'::jsonb, false, true),
  ('porcelain-onyx-silver', 'Onyx Silver', 'porselen', 'NG Stone', 'light', 'Parlak', '12 mm', 'Gümüş grisi oniks dalgaları. Banyo duvarı ve arkadan aydınlatmalı paneller için.', 'Silver-grey onyx waves. For bathroom walls and backlit panels.', '["/stones/porcelain-onyx-silver.jpg"]'::jsonb, false, true)
