-- Starting catalogue. Run after schema.sql. Safe to re-run (updates by slug).
on conflict (slug) do update set name = excluded.name, material = excluded.material, brand = excluded.brand, tone = excluded.tone, finish = excluded.finish, thickness = excluded.thickness, description_tr = excluded.description_tr, description_en = excluded.description_en, images = excluded.images, featured = excluded.featured, active = excluded.active;
